import bisect

class Solution:
    def maxCount(self, banned: list[int], n: int, maxSum: int) -> int:
        banned = sorted(list(set(x for x in banned if x <= n)))
        pref = [0] * (len(banned) + 1)
        for i in range(len(banned)):
            pref[i + 1] = pref[i] + banned[i]

        def check(M: int) -> bool:
            idx = bisect.bisect_right(banned, M)
            sum_total = M * (M + 1) // 2 - pref[idx]
            return sum_total <= maxSum

        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        idx = bisect.bisect_right(banned, lo)
        return lo - idx

class Solution {
public:
    int maxCount(std::vector<int>& banned, int n, long long maxSum) {
        std::sort(banned.begin(), banned.end());
        std::vector<long long> b;
        for (int x : banned) {
            if (x <= n && (b.empty() || b.back() != x)) b.push_back(x);
        }
        int m = b.size();
        std::vector<long long> pref(m + 1, 0);
        for (int i = 0; i < m; ++i) pref[i + 1] = pref[i] + b[i];

        auto check = [&](long long M) {
            int idx = std::upper_bound(b.begin(), b.end(), M) - b.begin();
            long long sum_total = M * (M + 1) / 2 - pref[idx];
            return sum_total <= maxSum;
        };

        long long lo = 0, hi = n;
        while (lo < hi) {
            long long mid = lo + (hi - lo + 1) / 2;
            if (check(mid)) lo = mid;
            else hi = mid - 1;
        }
        int idx = std::upper_bound(b.begin(), b.end(), lo) - b.begin();
        return (int)(lo - idx);
    }
};

class Solution {
    public int maxCount(int[] banned, int n, long maxSum) {
        java.util.Arrays.sort(banned);
        java.util.List<Long> b = new java.util.ArrayList<>();
        for (int x : banned) {
            if (x <= n && (b.isEmpty() || b.get(b.size() - 1) != x)) {
                b.add((long)x);
            }
        }
        int m = b.size();
        long[] pref = new long[m + 1];
        for (int i = 0; i < m; i++) pref[i + 1] = pref[i] + b.get(i);

        long lo = 0, hi = n;
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            int idx = upperSearch(b, mid);
            long sumTotal = mid * (mid + 1) / 2 - pref[idx];
            if (sumTotal <= maxSum) lo = mid;
            else hi = mid - 1;
        }
        int idx = upperSearch(b, lo);
        return (int)(lo - idx);
    }
    private int upperSearch(java.util.List<Long> b, long target) {
        int l = 0, r = b.size();
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (b.get(mid) <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }
}

var maxCount = function(banned, n, maxSum) {
    const b = Array.from(new Set(banned.filter(x => x <= n))).sort((x, y) => x - y);
    const m = b.length;
    const pref = new Array(m + 1).fill(0n);
    for (let i = 0; i < m; i++) pref[i + 1] = pref[i] + BigInt(b[i]);

    const upperSearch = (target) => {
        let l = 0, r = m;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (BigInt(b[mid]) <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    };

    const bMaxSum = BigInt(maxSum);
    let lo = 0n, hi = BigInt(n);
    while (lo < hi) {
        const mid = (lo + hi + 1n) / 2n;
        const idx = upperSearch(mid);
        const sumTotal = mid * (mid + 1n) / 2n - pref[idx];
        if (sumTotal <= bMaxSum) lo = mid;
        else hi = mid - 1n;
    }
    const idx = upperSearch(lo);
    return Number(lo - BigInt(idx));
};
